}

.header-title {
  font-size: 14px;
  text-transform: uppercase;
  font-weight: 600;
}

.salary-table {
  width: 100%;
  font-size: 11px;
  margin-bottom: 1px;
  border-collapse: collapse;
  border: 0.1px solid #000;
  table-layout: fixed;
}

.salary-table th,
.salary-table td {
  border: 0.1px solid #000;
  padding: 2px !important;
  font-size: 11px;
  font-family: Roboto, sans-serif;
  text-align: left;
  box-sizing: border-box;
}

.salary-table th {
  background-color: rgba(0, 0, 0, 0.05);
  font-weight: inherit;
}

.table-heading,
.table-total {
  color: #000 !important;
  font-size: 11px !important;
  font-weight: 600 !important;
}

.table-heading b,
.table-total b {
  color: #000 !important;
  font-size: inherit;
  font-weight: 600 !important;
}

.header-bracket {
  font-size: 75%;
  white-space: nowrap;
}

.salary-split-table {
  width: 100%;
  border-collapse: collapse;
  border-spacing: 0;
  table-layout: fixed;
  margin: 0 0 1px 0;
  padding: 0;
}

.salary-split-table td.salary-split-cell {
