html:
{% set employee = frappe.db.get_value("Employee", doc.employee, ["salutation", "date_of_joining", "branch", "grade", "custom_division", "custom_uan", "custom_pran", "custom_esic", "pan_number"], as_dict=True) or {} %}
{% set company_logo = frappe.db.get_value("Company", doc.company, "company_logo") %}
{% set company_address = frappe.db.sql("SELECT a.address_line1, a.address_line2, a.city, a.state, a.pincode FROM `tabAddress` a INNER JOIN `tabDynamic Link` dl ON dl.parent = a.name WHERE dl.parenttype = 'Address' AND dl.link_doctype = 'Company' AND dl.link_name = %s ORDER BY a.is_primary_address DESC, (a.address_type = 'Billing') DESC, a.creation ASC LIMIT 1", [doc.company], as_dict=True) %}
{% set salary_structure = frappe.get_doc("Salary Structure", doc.salary_structure) %}
{% set casual_leave = [0] %}
{% set earned_leave = [0] %}
{% for leave in doc.leave_details %}
    {% set leave_abbr = frappe.db.get_value("Leave Type", leave.leave_type, "custom_abbreviation") %}
    {% if leave_abbr == "EL" %}
        {% if earned_leave.append(earned_leave.pop() + leave.available_leaves) %}{% endif %}
    {% elif leave_abbr == "CL" %}
        {% if casual_leave.append(casual_leave.pop() + leave.available_leaves) %}{% endif %}
    {% endif %}
{% endfor %}
{% set row_count = doc.earnings|length if doc.earnings|length > doc.deductions|length else doc.deductions|length %}
<div class="salary-slip-format">
    <table class="slip-top">
        <tr>
            <td class="slip-left" colspan="2" style="width: 50%;"><span class="slip-title">Payslip</span><span class="slip-month-inline">{{ frappe.utils.formatdate(doc.start_date, "MMM yyyy").upper() }}</span></td>
            <td class="brand" style="width: 50%;">
                {% if company_logo %}<img src="{{ company_logo }}">
                {% elif doc.company == "Real Ispat and Power Ltd" %}<img src="/files/RIPL_FINAL.jpeg">
                {% elif doc.company == "API Ispat and Powertech Private Limited" %}<img src="/files/API_Logo.jpg">
                {% elif doc.company == "Real Ispat and Energy Private Limited" %}<img src="/files/RIEPL_FINAL.jpeg">
                {% elif doc.company == "Shivalay Ispat and Power Private Limited" %}<img src="/files/shivalay.jpg">{% endif %}
                <b>{{ doc.company }}</b>
                {% if company_address %}
                    {% set company_address_parts = [] %}
                    {% set address = company_address[0] %}
                    {% for part in [address.address_line1, address.address_line2, address.city, address.state, address.pincode] %}
                        {% if part and part not in company_address_parts %}{% if company_address_parts.append(part) %}{% endif %}{% endif %}
                    {% endfor %}
                    {% if company_address_parts %}<div class="company-address">{{ company_address_parts|join(", ") }}</div>{% endif %}
                {% endif %}
            </td>
        </tr>
    </table>
    <div class="slip-grid">
    <table class="detail-table">
        <colgroup><col style="width: 9.5%;"><col style="width: 11.5%;"><col style="width: 10.5%;"><col style="width: 10.5%;"><col style="width: 9%;"><col style="width: 8.25%;"><col style="width: 8.25%;"><col style="width: 10%;"><col style="width: 22.5%;"></colgroup>
        <tr><td class="employee-line" colspan="9">{% if employee.salutation %}{{ employee.salutation }} {% endif %}{{ doc.employee_name }}</td></tr>
        <tr class="section-head"><th colspan="4">Employee Details</th><th colspan="3">Payment and Leave Detail</th><th colspan="2">Location Details</th></tr>
        <tr><th class="nowrap-label">Employee #</th><td colspan="3">{{ doc.employee }}</td><th>Bank Name</th><td colspan="2">{{ doc.bank_name or "" }}</td><th>Location</th><td>{{ employee.branch or doc.branch or "" }}</td></tr>
        <tr><th>Designation</th><td colspan="3">{{ doc.designation or "" }}</td><th>Account #</th><td colspan="2">{{ doc.bank_account_no or "" }}</td><th>Division</th><td>{{ employee.custom_division or doc.custom_division or "" }}</td></tr>
        <tr><th>Grade</th><td>{{ employee.grade or doc.custom_grade or "" }}</td><th>Date Of Joining</th><td>{% if employee.date_of_joining %}{{ frappe.utils.formatdate(employee.date_of_joining) }}{% endif %}</td><th>Days Paid</th><td colspan="2">{{ doc.payment_days }}</td><th>Department</th><td>{{ doc.department or "" }}</td></tr>
        <tr><th>PAN</th><td>{{ employee.pan_number or "" }}</td><th>ESIC</th><td>{{ employee.custom_esic or doc.custom_esic or "" }}</td><th>Leave Balance</th><td class="leave-balance"><b>EL</b> <span>{{ earned_leave[0] }}</span></td><td class="leave-balance"><b>CL</b> <span>{{ casual_leave[0] }}</span></td><th class="identifier-label">UAN | PRAN</th><td class="identifier-value">{{ employee.custom_uan or "" }}{% if employee.custom_uan and employee.custom_pran %} | {% endif %}{{ employee.custom_pran or "" }}</td></tr>
    </table>
    <table class="bridge-row"><tr><td></td></tr></table>
    <table class="component-table">
        <tr class="component-head"><th style="width: 21%;">Earnings</th><th class="right" style="width: 11%;">Rate <span class="header-bracket">(INR)</span></th><th class="right" style="width: 13%;">Amount <span class="header-bracket">(INR)</span></th><th style="width: 27%;">Deductions</th><th class="right" style="width: 11%;">Amount <span class="header-bracket">(INR)</span></th><th class="right" style="width: 17%;">Year To Date <span class="header-bracket">(INR)</span></th></tr>
        {% for i in range(row_count) %}
        <tr>
            <td>{% if i < doc.earnings|length %}{{ doc.earnings[i].salary_component }}{% endif %}</td>
            <td class="right">{% if i < doc.earnings|length %}{% set slip_earning = doc.earnings[i] %}{% set structure_amount = [] %}{% set structure_formula = [] %}{% for row in salary_structure.earnings %}{% if row.salary_component == slip_earning.salary_component %}{% if structure_amount.append(row.amount) %}{% endif %}{% if structure_formula.append(row.amount_based_on_formula) %}{% endif %}{% endif %}{% endfor %}{% if structure_amount and structure_amount[0] > 0 %}{{ frappe.format(structure_amount[0], {"fieldtype": "Currency"}) }}{% elif structure_amount and structure_formula and structure_formula[0] %}{{ frappe.format(slip_earning.default_amount or 0, {"fieldtype": "Currency"}) }}{% endif %}{% endif %}</td>
            <td class="right">{% if i < doc.earnings|length %}{{ frappe.format(doc.earnings[i].amount, {"fieldtype": "Currency"}) }}{% endif %}</td>
            <td>{% if i < doc.deductions|length %}{{ doc.deductions[i].salary_component }}{% endif %}</td>
            <td class="right">{% if i < doc.deductions|length %}{{ frappe.format(doc.deductions[i].amount, {"fieldtype": "Currency"}) }}{% endif %}</td>
            <td class="right">{% if i < doc.deductions|length %}{{ frappe.format(doc.deductions[i].year_to_date, {"fieldtype": "Currency"}) }}{% endif %}</td>
        </tr>
        {% endfor %}
    </table>
    <table class="bridge-row"><tr><td></td></tr></table>
    <table class="totals">
        <tr><th style="width: 21%;">Total Earnings <span class="header-bracket">(INR)</span></th><td class="right" colspan="2" style="width: 24%; {% if doc.gross_pay > 99999 %}font-size: 12px;{% endif %}">{{ frappe.format(doc.gross_pay, {"fieldtype": "Currency"}) }}</td><th style="width: 27%;">Total Deductions <span class="header-bracket">(INR)</span></th><td class="right" style="width: 11%; {% if doc.total_deduction > 99999 %}font-size: 12px;{% endif %}">{{ frappe.format(doc.total_deduction, {"fieldtype": "Currency"}) }}</td><td style="width: 17%;"></td></tr>
    </table>
    {% if doc.loans %}
    <table class="loan-table">
        <tr class="component-head"><th style="width: 71.0526%;">Loan</th><th class="right repayment-heading" style="width: 28.9474%;">Repayment</th></tr>
        {% for loan in doc.loans %}
        <tr><td>{{ loan.loan }}</td><td class="right">{{ frappe.format(loan.total_payment, {"fieldtype": "Currency"}) }}</td></tr>
        {% endfor %}
    </table>
    {% endif %}
    </div>
    <table class="net-table"><tr><td class="net-label">Net Pay <span class="header-bracket">(INR)</span></td><td>{{ frappe.format(doc.net_pay, {"fieldtype": "Currency"}) }}</td></tr></table>
    <div class="signature-note">This is a system-generated pay slip and does not require a signature</div>
</div>

css:
@page {
  size: A4;
  margin: 15mm 15mm 15mm 15mm !important; /* top, right, bottom, left */
}

body {
  font-family: Roboto, sans-serif;
  font-size: 11px;
  margin: 0 !important;  /* reset browser default */
  padding: 0 3mm !important;
}

.header {
  display: flex;
  justify-content: center;
  margin-bottom: 2px;
}

.header-title {
  font-size: 14px;
  text-transform: uppercase;
  font-weight: 600;
}

.salary-table {
  width: 100%;
  font-size: 11px;
  margin-bottom: 1px;
  border-collapse: collapse;
  border: 0.1px solid #000;
  table-layout: fixed;
}

.salary-table th,
.salary-table td {
  border: 0.1px solid #000;
  padding: 2px !important;
  font-size: 11px;
  font-family: Roboto, sans-serif;
  text-align: left;
  box-sizing: border-box;
}

.salary-table th {
  background-color: rgba(0, 0, 0, 0.05);
  font-weight: inherit;
}

.table-heading,
.table-total {
  color: #000 !important;
  font-size: 11px !important;
  font-weight: 600 !important;
}

.table-heading b,
.table-total b {
  color: #000 !important;
  font-size: inherit;
  font-weight: 600 !important;
}

.header-bracket {
  font-size: 75%;
  white-space: nowrap;
}

.salary-split-table {
  width: 100%;
  border-collapse: collapse;
  border-spacing: 0;
  table-layout: fixed;
  margin: 0 0 1px 0;
  padding: 0;
}

.salary-split-table td.salary-split-cell {
  width: 50%;
  padding: 0 !important;
  vertical-align: top;
  border: 0 !important;
}

.salary-half-table {
  width: 100%;
  margin: 0 !important;
  border-collapse: collapse;
  border-spacing: 0;
}

.salary-half-table th {
  text-align: right;
}

.salary-half-table th,
.salary-half-table td {
  height: 14px;
  line-height: 1;
  vertical-align: middle;
}

.salary-blank-row td {
  font-size: 11px;
  font-weight: 500;
  line-height: 1;
}

.salary-split-left .salary-half-table {
  border-right: 0;
}

.salary-split-right .salary-half-table {
  border-left: 0;
}

.salary-split-right .salary-half-table th:first-child,
.salary-split-right .salary-half-table td:first-child {
  border-left: 0;
}

.employee-detail-table {
  table-layout: fixed;
}

.employee-detail-table td {
  word-break: normal;
}

.employee-detail-combined {
  border: 0 !important;
}

.employee-detail-combined .employee-photo-cell {
  border: 0.1px solid #000 !important;
  padding: 6px 1px 1px 1px !important;
  text-align: center;
  vertical-align: middle;
  overflow: hidden;
}

.employee-detail-combined .employee-photo-cell img {
  max-width: 100%;
  width: 95px;
  height: 95px;
  display: block;
  margin: 0 auto;
}


.emp_details {
  display: flex;
  width: 100%;
  align-items: flex-start;
}

.emp_details > .salary-table {
  flex: 0 0 83.33%;
  width: 83.33%;
}

.emp_details > .image {
  flex: 0 0 16.67%;
  width: 16.67%;
  margin-top: -3mm !important;
  padding-left: 3mm;
  box-sizing: border-box;
  table-layout: fixed;
  border-collapse: collapse;
}

.emp_details > .image td {
  border: 0;
  width: 100%;
  text-align: center;
  vertical-align: top;
  padding: 0;
}

.emp_details > .image img {
  width: 105px;
  height: 100px;
  display: block;
  margin: 0 auto;
}
